-    return transform(makeFuture<KJob *>(KIO::del({QUrl::fromLocalFile(device.data()), QUrl::fromLocalFile(mountPoint.data())})), [](KJob *job) {
+    QList<QUrl> urls{QUrl::fromLocalFile(device.data())};
