-                    // lock the mountpoint when the vault is closed
+                    // lock or remove the mountpoint when the vault is closed
                     if (newStatus == VaultInfo::Closed)
-                        data->backend->lockMountPoint(data->mountPoint, true);
+                        closeMountPoint();
                 }

                 if (oldStatus == VaultInfo::NotInitialized //
@@ -247,6 +250,7 @@ public:
         const QString backendName    = payload[KEY_BACKEND].toString();
         const QStringList activities = payload[KEY_ACTIVITIES].toStringList();
         const bool isOfflineOnly     = payload[KEY_OFFLINEONLY].toBool();
+        const bool removesMountPoint = payload[KEY_REMOVEMOUNTPOINT].toBool();

         // status should never be in this state, if we got an error,
         // d->data should not be valid
@@ -258,6 +262,7 @@ public:
         vaultData.backendName   = vaultConfig.readEntry(CFG_BACKEND, backendName);
         vaultData.activities    = vaultConfig.readEntry(CFG_ACTIVITIES, activities);
         vaultData.isOfflineOnly = vaultConfig.readEntry(CFG_OFFLINEONLY, isOfflineOnly);
+        vaultData.removesMountPoint = vaultConfig.readEntry(CFG_REMOVEMOUNTPOINT, removesMountPoint);

         const QString configuredMountPoint = vaultConfig.readEntry(CFG_MOUNT_POINT, mountPoint.data());
         vaultData.mountPoint = MountPoint(configuredMountPoint);
@@ -331,7 +336,25 @@ public:
         });
     }

+    void closeMountPoint()
+    {
+        if (data->removesMountPoint) {
+            data->backend->lockMountPoint(data->mountPoint, false);
+
+            // only remove the mount point if nothing but our .directory file is left in it
+            QDir dir(data->mountPoint.data());
+            const auto entries = dir.entryList(QDir::NoDotAndDotDot | QDir::AllEntries | QDir::Hidden | QDir::System);
+            if (entries == QStringList{QStringLiteral(".directory")}) {
+                dir.remove(QStringLiteral(".directory"));
+            }
+
+            if (!dir.exists() || QDir().rmdir(data->mountPoint.data())) {
+                return;
+            }
+        }

+        data->backend->lockMountPoint(data->mountPoint, true);
+    }

     bool isInitialized() const
     {
@@ -452,6 +475,11 @@ FutureResult<> Vault::import(const QString &name, const MountPoint &mountPoint,

 FutureResult<> Vault::open(const Payload &payload)
 {
+    // The mount point might have been removed when the vault was locked
+    if (d->data && !QDir().mkpath(d->data->mountPoint.data())) {
+        return errorResult(Error::MountPointError, i18n("Cannot create the mount point"));
+    }
+
     return
         // We can not mount something that has not been registered
         // with us before
@@ -726,7 +754,28 @@ void Vault::setIsOfflineOnly(bool isOfflineOnly)
     saveConfiguration();
 }

+bool Vault::removesMountPoint() const
+{
+    return d->data->removesMountPoint;
+}

+void Vault::setRemovesMountPoint(bool removesMountPoint)
+{
+    if (d->data->removesMountPoint == removesMountPoint) {
+        return;
+    }
+
+    d->data->removesMountPoint = removesMountPoint;
+
+    if (status() == VaultInfo::Closed) {
+        if (!removesMountPoint) {
+            QDir().mkpath(d->data->mountPoint.data());
+        }
+        d->closeMountPoint();
+    }
+
+    saveConfiguration();
+}

 QString Vault::name() const
 {
